css:
/* Claude Desktop Dark — Claude Desktop flavour for T3 Code */

/* Composer：悬浮大圆角卡片 */
[data-slot="composer-host"] {
  border-radius: 16px !important;
}
.dark [data-slot="composer-host"] {
  box-shadow: 0 0 0 0.5px rgba(59, 57, 52, 0.55), 0 1px 2px rgba(0, 0, 0, 0.22), 0 10px 28px -8px rgba(0, 0, 0, 0.5) !important;
}

/* 用户消息：圆润胶囊气泡 */
[data-user-message-bubble] {
  border-radius: 18px !important;
  padding: 10px 16px !important;
  line-height: 1.55;
}

/* 弱化顶栏与侧边栏分割线 */
.dark [data-chat-header] {
  border-bottom-color: rgba(47, 45, 41, 0.4) !important;
  box-shadow: none !important;
}
.dark [data-slot="sidebar"],
.dark [data-slot="sidebar-inner"] {
  border-color: rgba(38, 36, 31, 0.4) !important;
}

/* 代码块：10px 圆角 + 暖色细描边 */
.chat-markdown-codeblock {
  border-radius: 10px !important;
  overflow: hidden;
}
.dark .chat-markdown-codeblock {
  border: 1px solid rgba(59, 57, 52, 0.75) !important;
}

/* Lucide 图标：更精致的线宽 */
svg.lucide {
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* 浮层与会话项：圆润 + 柔和阴影 */
[data-slot="popover-popup"],
[data-slot="menu-popup"],
[data-slot="dialog-popup"] {
  border-radius: 12px !important;
}
[data-slot="tooltip-popup"] {
  border-radius: 7px !important;
}
[data-thread-item] {
  border-radius: 8px !important;
}
[data-slot="project-monogram"] {
  border-radius: 6px !important;
}
.dark [data-slot="popover-popup"],
.dark [data-slot="menu-popup"],
.dark [data-slot="dialog-popup"] {
  box-shadow: 0 0 0 0.5px rgba(59, 57, 52, 0.7), 0 16px 40px -12px rgba(0, 0, 0, 0.6) !important;
}

/* 暖灰细滚动条 */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-thumb {
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
.dark ::-webkit-scrollbar-thumb {
  background-color: rgba(156, 152, 142, 0.28);
}
.dark ::-webkit-scrollbar-thumb:hover {
  background-color: rgba(156, 152, 142, 0.45);
}
.dark [data-slot="scroll-area-thumb"] {
  background-color: rgba(156, 152, 142, 0.32) !important;
}
